import{_ as d,o,c as e,a2 as a}from"./chunks/framework.C4u7U0Dw.js";const u=JSON.parse('{"title":"第 25 章 内置技能库（二）：文档、表格与演示","description":"","frontmatter":{},"headers":[],"relativePath":"bluebook/第五篇 平台能力全景/第 25 章 内置技能库（二）：文档、表格与演示.md","filePath":"bluebook/第五篇 平台能力全景/第 25 章 内置技能库（二）：文档、表格与演示.md"}'),r={name:"bluebook/第五篇 平台能力全景/第 25 章 内置技能库（二）：文档、表格与演示.md"};function c(n,t,s,l,i,p){return o(),e("div",null,[...t[0]||(t[0]=[a(`<h1 id="第-25-章-内置技能库-二-文档、表格与演示" tabindex="-1">第 25 章 内置技能库（二）：文档、表格与演示 <a class="header-anchor" href="#第-25-章-内置技能库-二-文档、表格与演示" aria-label="Permalink to &quot;第 25 章 内置技能库（二）：文档、表格与演示&quot;">​</a></h1><blockquote><p>本章目标：学会把&quot;内容&quot;变成<strong>能直接交出去的文件</strong>。12 个交付类技能分成三个家族（Word / Excel / PPT）和一个通用组（图表 / PDF），理解它们的分层逻辑，你就知道该派谁上。<strong>能生成内容只是及格，能交付文件才算完成。</strong></p></blockquote><h2 id="_25-1-交付物的分水岭-能生成-能交付" tabindex="-1">25.1 交付物的分水岭：能生成 ≠ 能交付 <a class="header-anchor" href="#_25-1-交付物的分水岭-能生成-能交付" aria-label="Permalink to &quot;25.1 交付物的分水岭：能生成 ≠ 能交付&quot;">​</a></h2><p>一个很典型的场景：</p><blockquote><p>你让我写一份项目方案。我给了你 3000 字的 Markdown。然后你还要：复制到 Word、调标题样式、加页眉、做目录、改字体……</p></blockquote><p><strong>这段&quot;再加工&quot;的时间，往往比写内容本身还长。</strong></p><p>交付类技能要解决的就是这个：<strong>让产出直接是别人能打开、能打印、能签字的文件</strong>。</p><table tabindex="0"><thead><tr><th>层次</th><th>产出</th><th>你的后续动作</th></tr></thead><tbody><tr><td>内容层</td><td>Markdown / 纯文本</td><td>排版、转格式、调样式（你自己干）</td></tr><tr><td>交付层</td><td><code>.docx</code> / <code>.xlsx</code> / <code>.pptx</code> / <code>.pdf</code></td><td>打开就能用（我干完了）</td></tr></tbody></table><p>这一章的所有技能，都在第二层。</p><h2 id="_25-2-一张表看懂-12-个交付类技能" tabindex="-1">25.2 一张表看懂 12 个交付类技能 <a class="header-anchor" href="#_25-2-一张表看懂-12-个交付类技能" aria-label="Permalink to &quot;25.2 一张表看懂 12 个交付类技能&quot;">​</a></h2><table tabindex="0"><thead><tr><th>家族</th><th>技能</th><th>什么时候用</th></tr></thead><tbody><tr><td>📄 Word</td><td><code>officecli-docx</code></td><td>报告、方案、信函、备忘录、提案；读写改任何 <code>.docx</code></td></tr><tr><td>📄 Word</td><td><code>officecli-word-form</code></td><td><strong>可填写表单</strong>：入职表、问卷、合同模板、合规清单</td></tr><tr><td>📄 Word</td><td><code>officecli-academic-paper</code></td><td>论文/期刊/会议稿：APA/Chicago/IEEE/MLA 引用、编号公式、参考文献</td></tr><tr><td>📊 Excel</td><td><code>officecli-xlsx</code></td><td>表格、追踪表、预算表；CSV 转 Excel、公式、图表、透视表</td></tr><tr><td>📊 Excel</td><td><code>officecli-data-dashboard</code></td><td><strong>数据看板</strong>：KPI 卡片 + 多图表 + 迷你图 + 条件格式</td></tr><tr><td>📊 Excel</td><td><code>officecli-financial-model</code></td><td><strong>财务模型</strong>：三表模型、DCF、LBO、敏感性分析、单位经济</td></tr><tr><td>📽️ PPT</td><td><code>officecli-pptx</code></td><td>演示文稿、汇报、销售材料；合并/拆分、模板、备注</td></tr><tr><td>📽️ PPT</td><td><code>officecli-pitch-deck</code></td><td><strong>融资路演</strong>：种子轮 / A / B / C 轮、SAFE、可转债</td></tr><tr><td>📽️ PPT</td><td><code>morph-ppt</code></td><td><strong>跨页平滑动画</strong>：Morph 过渡、形状生长/移动/旋转</td></tr><tr><td>📽️ PPT</td><td><code>morph-ppt-3d</code></td><td>在 morph 基础上加 <strong>GLB 三维模型</strong> + 电影级镜头</td></tr><tr><td>📐 图表</td><td><code>mermaid</code></td><td>流程图、时序图、状态图、类图、ER 图（SVG 或 ASCII）</td></tr><tr><td>📎 PDF</td><td><code>pdf</code></td><td>文本/表格提取、创建、合并拆分、<strong>表单填写</strong>、批量处理</td></tr></tbody></table><h2 id="_25-3-基础层-场景层-这套架构为什么要懂" tabindex="-1">25.3 基础层 + 场景层：这套架构为什么要懂 <a class="header-anchor" href="#_25-3-基础层-场景层-这套架构为什么要懂" aria-label="Permalink to &quot;25.3 基础层 + 场景层：这套架构为什么要懂&quot;">​</a></h2><p>这是本章最值得记住的设计。Office 技能不是 12 个并列工具，而是<strong>两层结构</strong>：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>基础层（通用能力，管所有硬规则）</span></span>
<span class="line"><span>├── officecli-docx</span></span>
<span class="line"><span>├── officecli-xlsx</span></span>
<span class="line"><span>└── officecli-pptx</span></span>
<span class="line"><span>        │ 继承（场景层会继承基础层的每一条硬规则）</span></span>
<span class="line"><span>        ▼</span></span>
<span class="line"><span>场景层（专业交付物，管&quot;这类文件该长什么样&quot;）</span></span>
<span class="line"><span>├── docx 场景层：officecli-academic-paper</span></span>
<span class="line"><span>├── xlsx 场景层：officecli-data-dashboard、officecli-financial-model</span></span>
<span class="line"><span>└── pptx 场景层：officecli-pitch-deck、morph-ppt、morph-ppt-3d</span></span></code></pre></div><p><strong>类比的例子</strong>：基础层像&quot;会做木工&quot;，场景层像&quot;专门做橱柜的师傅&quot;——后者会做前者所有的事，外加一套行业规矩。</p><p><strong>这对你有什么用？</strong></p><table tabindex="0"><thead><tr><th>场景</th><th>该找谁</th><th>原因</th></tr></thead><tbody><tr><td>一份普通周报 .docx</td><td><code>officecli-docx</code></td><td>基础层足够</td></tr><tr><td>一个简单的预算追踪表</td><td><code>officecli-xlsx</code></td><td>不要用看板技能杀鸡用牛刀</td></tr><tr><td>从 CSV 生成管理层看板</td><td><code>officecli-data-dashboard</code></td><td>需要 KPI 卡片 + 图表体系</td></tr><tr><td>一份三表模型 / DCF</td><td><code>officecli-financial-model</code></td><td>需要财务专业规范</td></tr><tr><td>董事会评审 PPT</td><td><code>officecli-pptx</code></td><td>通用演示</td></tr><tr><td>融资路演 PPT</td><td><code>officecli-pitch-deck</code></td><td>需要投资人视角的结构</td></tr><tr><td>带跨页动画的产品发布</td><td><code>morph-ppt</code></td><td>需要 Morph 过渡</td></tr></tbody></table><blockquote><p>判断口诀：<strong>通用就用基础层，专业就用场景层。</strong> 场景层不是&quot;更高级&quot;，而是&quot;更对口&quot;。</p></blockquote><h3 id="_25-3-1-一个重要特性-独立技能" tabindex="-1">25.3.1 一个重要特性：独立技能 <a class="header-anchor" href="#_25-3-1-一个重要特性-独立技能" aria-label="Permalink to &quot;25.3.1 一个重要特性：独立技能&quot;">​</a></h3><p>有一个例外——<code>officecli-word-form</code>（可填写表单）<strong>不是</strong> docx 的场景层，它是<strong>独立技能</strong>。</p><p>原因很技术：可填写表单用到的是内容控件（SDT）、传统表单域、邮件合并占位符和文档保护，这些能力<strong>基础层完全没有覆盖</strong>，不是&quot;继承 + 增强&quot;的关系，而是另一套东西。</p><p><strong>对你的意义</strong>：当你要&quot;只有指定字段能填、其他全锁住&quot;的表单时，别说&quot;做个 Word 文档&quot;，直接说**&quot;做一个可填写的表单模板&quot;**，我就会派对技能。</p><h2 id="_25-4-word-家族-文档、表单、论文" tabindex="-1">25.4 Word 家族：文档、表单、论文 <a class="header-anchor" href="#_25-4-word-家族-文档、表单、论文" aria-label="Permalink to &quot;25.4 Word 家族：文档、表单、论文&quot;">​</a></h2><table tabindex="0"><thead><tr><th>你要什么</th><th>怎么说最有效</th></tr></thead><tbody><tr><td>常规报告/方案</td><td>&quot;写一份 XX 方案，输出 Word，要有目录和页眉&quot;</td></tr><tr><td>可填写表单</td><td>&quot;做一份新员工入职信息表，Word 格式，只有填写区可编辑&quot;</td></tr><tr><td>学术稿件</td><td>&quot;把这篇整理成 IEEE 双栏格式，参考文献用 IEEE 引用规范&quot;</td></tr></tbody></table><p><strong>论文场景值得多说一句</strong>：<code>officecli-academic-paper</code> 支持 APA / Chicago / IEEE / MLA 四套引用规范、编号公式、图表交叉引用、脚注尾注、参考文献悬挂缩进、多栏期刊布局。以前这些要手动调一整天，现在一次说清楚就行。</p><h2 id="_25-5-excel-家族-表格、看板、财务模型" tabindex="-1">25.5 Excel 家族：表格、看板、财务模型 <a class="header-anchor" href="#_25-5-excel-家族-表格、看板、财务模型" aria-label="Permalink to &quot;25.5 Excel 家族：表格、看板、财务模型&quot;">​</a></h2><p>三个技能是层层递进的关系：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>officecli-xlsx           ← 基础：数据、公式、图表、透视表</span></span>
<span class="line"><span>   ├── data-dashboard    ← 场景：KPI 卡片 + 多图表 + 条件格式（给管理层看）</span></span>
<span class="line"><span>   └── financial-model   ← 场景：三表 / DCF / LBO / 敏感性（给财务和投资人看）</span></span></code></pre></div><p><strong>关键判断</strong>：</p><ul><li>一张表、十几行、最多一个图 → <strong>基础层</strong>（<code>officecli-xlsx</code>）</li><li>多张 KPI 卡片 + 多图表 + 迷你图 + 条件格式 → <strong>看板</strong>（<code>officecli-data-dashboard</code>）</li><li>有&quot;预测、估值、场景、单位经济&quot;这类字眼 → <strong>财务模型</strong>（<code>officecli-financial-model</code>）</li></ul><blockquote><p>常见误用：拿 <code>financial-model</code> 去做一张简单的费用报销表。结果是过度设计、交付变慢。<strong>专业能力用在专业场景，才是效率。</strong></p></blockquote><h2 id="_25-6-ppt-家族-演示、路演、动画" tabindex="-1">25.6 PPT 家族：演示、路演、动画 <a class="header-anchor" href="#_25-6-ppt-家族-演示、路演、动画" aria-label="Permalink to &quot;25.6 PPT 家族：演示、路演、动画&quot;">​</a></h2><table tabindex="0"><thead><tr><th>需求关键词</th><th>派谁</th><th>输出特点</th></tr></thead><tbody><tr><td>汇报 / 评审 / 培训</td><td><code>officecli-pptx</code></td><td>结构清晰的标准演示</td></tr><tr><td>融资 / 路演 / 投资人</td><td><code>officecli-pitch-deck</code></td><td>按投资人关注点组织</td></tr><tr><td>&quot;要丝滑的跨页动画&quot;</td><td><code>morph-ppt</code></td><td>形状跨页连续运动</td></tr><tr><td>&quot;要有 3D 模型 / 电影感镜头&quot;</td><td><code>morph-ppt-3d</code></td><td>GLB 模型 + 摄像机语言</td></tr></tbody></table><p><strong><code>morph-ppt</code> 的效果是什么样？</strong> 简单说：<strong>同一个形状，在第 2 页变成另一种形态</strong>。不是&quot;淡入淡出&quot;，而是&quot;这一个东西长成了那个东西&quot;。做产品演进、流程变化、数据增长这类叙事时，效果非常抓人。</p><h2 id="_25-7-图表与-pdf-两个万能工具" tabindex="-1">25.7 图表与 PDF：两个万能工具 <a class="header-anchor" href="#_25-7-图表与-pdf-两个万能工具" aria-label="Permalink to &quot;25.7 图表与 PDF：两个万能工具&quot;">​</a></h2><h3 id="_25-7-1-mermaid-把逻辑画出来" tabindex="-1">25.7.1 Mermaid：把逻辑画出来 <a class="header-anchor" href="#_25-7-1-mermaid-把逻辑画出来" aria-label="Permalink to &quot;25.7.1 Mermaid：把逻辑画出来&quot;">​</a></h3><p>支持五类图：<strong>流程图、时序图、状态图、类图、ER 图</strong>。而且有两种输出：</p><table tabindex="0"><thead><tr><th>输出形式</th><th>用在哪</th></tr></thead><tbody><tr><td>SVG（矢量图）</td><td>文档、PPT、网页里插图</td></tr><tr><td>ASCII / Unicode</td><td>直接贴在聊天、代码注释、终端里</td></tr></tbody></table><blockquote><p>实用场景：讨论流程时，我直接给你一张 ASCII 流程图贴进消息里，比来回文字描述快十倍。</p></blockquote><h3 id="_25-7-2-pdf-不只是-转成-pdf" tabindex="-1">25.7.2 PDF：不只是&quot;转成 PDF&quot; <a class="header-anchor" href="#_25-7-2-pdf-不只是-转成-pdf" aria-label="Permalink to &quot;25.7.2 PDF：不只是&quot;转成 PDF&quot;&quot;">​</a></h3><p>这个技能能做的不止导出：</p><table tabindex="0"><thead><tr><th>能力</th><th>典型用法</th></tr></thead><tbody><tr><td>提取文本与表格</td><td>从扫描件/年报里把数据抠出来</td></tr><tr><td>创建 / 合并 / 拆分</td><td>把 20 份合同合成一份归档</td></tr><tr><td><strong>表单填写</strong></td><td>程序化填写 PDF 表单（含字段检测与校验）</td></tr><tr><td>批量处理</td><td>按规则批量转换、命名、归档</td></tr></tbody></table><h2 id="_25-8-交付门禁-我为什么会在交付前来回确认" tabindex="-1">25.8 交付门禁：我为什么会在交付前来回确认 <a class="header-anchor" href="#_25-8-交付门禁-我为什么会在交付前来回确认" aria-label="Permalink to &quot;25.8 交付门禁：我为什么会在交付前来回确认&quot;">​</a></h2><p>Office 类技能里有一个贯穿始终的机制，叫<strong>交付门禁（Delivery Gate）</strong>。</p><p>它的表现是：<strong>我不会闷头做完直接丢给你一个文件，而是会在关键节点停下来跟你对一遍。</strong></p><table tabindex="0"><thead><tr><th>环节</th><th>我会确认什么</th></tr></thead><tbody><tr><td>开工前</td><td>交付物类型、受众、篇幅、风格、有没有模板</td></tr><tr><td>结构定型</td><td>大纲/页面骨架对不对</td></tr><tr><td>视觉规范</td><td>配色、字号、网格、图表样式</td></tr><tr><td>交付前</td><td>内容准确性、格式一致性、有没有明显问题</td></tr></tbody></table><p><strong>为什么要这么&quot;啰嗦&quot;？</strong></p><p>因为文件型交付物的<strong>返工成本极高</strong>：PPT 做到第 30 页发现结构错了，等于前面全废；财务模型表间勾稽错了，可能直接误导决策。</p><blockquote><p>记住一句话：<strong>在文档里，停下来问一句的成本，永远低于推倒重来的成本。</strong></p></blockquote><p>反过来说，如果你想让我少问多干，也可以明确告诉我：<em>&quot;结构你定，直接出稿，我最后再调。&quot;</em> ——我会照办，但风险你担。</p><h2 id="_25-9-本章练习" tabindex="-1">25.9 本章练习 <a class="header-anchor" href="#_25-9-本章练习" aria-label="Permalink to &quot;25.9 本章练习&quot;">​</a></h2><ol><li><strong>替换一次手工排版</strong>：找出你这周做过的、需要&quot;复制到 Office 里再排版&quot;的活儿，下次直接要交付格式。</li><li><strong>做一次分层判断</strong>：下面三个需求分别该派谁？ <ul><li>一份 8 页的产品介绍 PPT</li><li>一张 12 个 KPI 的运营看板</li><li>一份带书签和填写区的报名表</li></ul></li><li><strong>试一次 Mermaid</strong>：把你手头一个流程（哪怕是&quot;请假审批&quot;）用文字描述给我，要一张流程图。</li></ol><hr><blockquote><p>小结：交付类技能的价值不在&quot;我能生成文件&quot;，而在&quot;<strong>你不用再做二次加工</strong>&quot;。记住三层结构——<strong>基础层管通用、场景层管专业、独立技能管特殊</strong>——你就能在 12 个技能里精准点名。</p></blockquote>`,54)])])}const b=d(r,[["render",c]]);export{u as __pageData,b as default};
